CREATE TABLE `detail_penjualan` (
  `id_detail_penjualan` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `id_penjualan` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
