  `persen_diskon` decimal(5,2) NOT NULL DEFAULT '0.00',
  `id_promo` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id_detail_penjualan`),
