--
-- Table structure for table `pengeluaran`
--

DROP TABLE IF EXISTS `pengeluaran`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `pengeluaran` (
  `id_pengeluaran` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `id_akun` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `id_pembelian` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tanggal_pengeluaran` datetime NOT NULL,
  `jenis_pengeluaran` enum('PEMBELIAN_PRODUK','LISTRIK','INTERNET','SEWA','ONGKIR','PERAWATAN','LAINNYA') COLLATE utf8mb4_unicode_ci NOT NULL,
  `nominal` decimal(12,2) NOT NULL,
  `keterangan` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id_pengeluaran`),
  UNIQUE KEY `pengeluaran_id_pembelian_unique` (`id_pembelian`),
  KEY `pengeluaran_id_akun_foreign` (`id_akun`),
  CONSTRAINT `pengeluaran_id_akun_foreign` FOREIGN KEY (`id_akun`) REFERENCES `akun` (`id_akun`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `pengeluaran_id_pembelian_foreign` FOREIGN KEY (`id_pembelian`) REFERENCES `pembelian_produk` (`id_pembelian`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

